Q: How can I flock LOCK_EX if there is always a LOCK_SH? A: <blockquote>
<p>Is there any way to block new shared flocks while there is an exclusive flock pending?</p>
</blockquote>
<p>Yes. The writer thread can indicate to the reader threads that it wants access to the lock by setting an atomic variable (such as an <code>atomic_bool</code>) to a certain value (e.g. <code>true</code>). If all reader threads check this variable before attempting to acquire the shared lock, and don't attempt to acquire the lock as long as this variable is set to that value, then the writer will effectively have priority over the read threads.</p>
<p>As far as I can tell, the pthreads library does not offer an efficient way for the reader thread to wait for the writer thread to be finished and the atomic variable to be reset to its original value. Using a pthreads condition variable would be inefficient, as this would require every reader thread to acquire a mutex. However, Linux allows you to create an &quot;event&quot; file descriptor using the <a href="https://man7.org/linux/man-pages/man2/eventfd.2.html" rel="nofollow noreferrer"><code>eventfd</code></a> system call. A writer thread can signal this event when it is finished, and a reader thread can wait for this event to become signalled using <a href="https://man7.org/linux/man-pages/man2/poll.2.html" rel="nofollow noreferrer"><code>poll</code></a> or <a href="https://man7.org/linux/man-pages/man7/epoll.7.html" rel="nofollow noreferrer"><code>epoll</code></a>. See the following Stack Overflow question for further information:</p>
<p><a href="https://stackoverflow.com/q/77905421/12149471">Linux - how to wait on event without using mutex</a></p>
<p>Here is a working example:</p>
<pre><code>/*
 * if VERBOSE is defined, the shared threads will
 * list every flock &amp; unflock.
 */

#define VERBOSE

#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;stdatomic.h&gt;
#include &lt;stdbool.h&gt;
#include &lt;stdint.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/file.h&gt;
#include &lt;sys/eventfd.h&gt;
#include &lt;pthread.h&gt;
#include &lt;poll.h&gt;

atomic_bool g_writer_wants_access = false;
int g_event;

void exclusive_flock()
{
    uint64_t event_val;

    // tell the reader threads to back off
    g_writer_wants_access = true;
    if ( read( g_event, &amp;event_val, sizeof event_val ) != sizeof event_val )
    {
        fprintf( stderr, &quot;Error setting event!\n&quot; );
        exit( EXIT_FAILURE );
    }

    int fd = open( &quot;flockfile&quot;, O_RDWR | O_CREAT | O_TRUNC );

    printf(&quot;Waiting on exclusive flock\n&quot;);
    flock(fd, LOCK_EX);
    printf(&quot;Lock successfull!\n&quot;);

    flock(fd, LOCK_UN);
    printf(&quot;Unlocked\n&quot;);

    // tell the reader threads that they may again proceed as usual
    g_writer_wants_access = false;
    event_val = 1;
    if ( write( g_event, &amp;event_val, sizeof event_val ) != sizeof event_val )
    {
        fprintf(stderr, &quot;Error setting event!\n&quot;);
    }

    close(fd);
}

void *shared_thread_routine(void *threadnum_data)
{
    int *pthreadnum = (int *)threadnum_data;
    int threadnum = *pthreadnum;
    printf(&quot;thread %d starting to juggle shared flocks\n&quot;, threadnum);
    // these threads get shared flocks for a while then
    // release them.
    // Since they are shared, they get issued immediately
    // (unless an exclusive flock succeeds).
    // they overlap, so there is never a time when none
    // of the threads have a shared flock.
    for (int i = 0; i &lt; 30; i++)
    {
        int fd = open(&quot;flockfile&quot;, O_RDWR | O_CREAT | O_TRUNC);

        // determine whether to give way to writer thread
        if ( g_writer_wants_access )
        {
            struct pollfd pfd = { g_event, POLLIN, 0 };

            // wait for writer thread to finish
            if ( poll( &amp;pfd, 1, -1 ) &lt; 1 || pfd.revents &amp; POLLIN == 0 )
            {
                fprintf( stderr, &quot;Error waiting for writer thread!\n&quot; );
                exit( EXIT_FAILURE );
            }
        }

        // open a shared flock
        flock(fd, LOCK_SH);

#ifdef VERBOSE
        printf(&quot;thread %d has a shared flock on fd %d\n&quot;, threadnum, fd);
#endif

        // read the file, do some work
        sleep(1);

        // release the flock; hopefully give exclusive_thread a chance:
        flock(fd, LOCK_UN);
        close(fd);

#ifdef VERBOSE
        printf(&quot;thread %d has released it's flock on fd %d\n&quot;, threadnum, fd);
#endif

        // a short delay between runs
        usleep(4000 * (threadnum) );
    }
    printf(&quot;thread %d done\n&quot;, threadnum);
}

int main (int argc, char **argv)
{
    pthread_t threads[10];

    // create event file descriptor
    g_event = eventfd( 1, EFD_NONBLOCK );
    if (g_event &lt; 0)
    {
        fprintf(stderr, &quot;Error creating event!\n&quot;);
        exit( EXIT_FAILURE);
    }

    // create the reader threads
    for ( int threadnum = 0; threadnum &lt; 10; threadnum++ )
    {
        pthread_create( &amp;threads[threadnum], NULL, shared_thread_routine, &amp;threadnum);
        usleep(1000);
    }

    // attempt to obtain exlusive access using the writer thread
    exclusive_flock();

    // join all the threads
    for ( int threadnum = 0; threadnum &lt; 10; threadnum++ )
    {
        pthread_join( threads[threadnum], NULL );
    }

    // cleanup
    close(g_event);
}
</code></pre>
<p>This program has the following behavior:</p>
